export interface MarketOutcome {
    /** Outcome ID for trading operations (CLOB Token ID for Polymarket, Market Ticker for Kalshi) */
    outcomeId: string;
    /** The market this outcome belongs to (set automatically when outcomes are built) */
    marketId?: string;
    label: string;
    price: number;
    priceChange24h?: number;
    metadata?: Record<string, any>;
}
export interface UnifiedEvent {
    id: string;
    title: string;
    description: string;
    slug: string;
    markets: UnifiedMarket[];
    volume24h: number;
    volume?: number;
    url: string;
    image?: string;
    category?: string;
    tags?: string[];
}
export interface UnifiedMarket {
    /** The unique identifier for this market */
    marketId: string;
    eventId?: string;
    title: string;
    description: string;
    slug?: string;
    outcomes: MarketOutcome[];
    resolutionDate: Date;
    volume24h: number;
    volume?: number;
    liquidity: number;
    openInterest?: number;
    url: string;
    image?: string;
    category?: string;
    tags?: string[];
    tickSize?: number;
    yes?: MarketOutcome;
    no?: MarketOutcome;
    up?: MarketOutcome;
    down?: MarketOutcome;
}
export type CandleInterval = '1m' | '5m' | '15m' | '1h' | '6h' | '1d';
export interface PriceCandle {
    timestamp: number;
    open: number;
    high: number;
    low: number;
    close: number;
    volume?: number;
}
export interface OrderLevel {
    price: number;
    size: number;
}
export interface OrderBook {
    bids: OrderLevel[];
    asks: OrderLevel[];
    timestamp?: number;
}
export interface Trade {
    id: string;
    timestamp: number;
    price: number;
    amount: number;
    side: 'buy' | 'sell' | 'unknown';
    outcomeId?: string;
}
export interface UserTrade extends Trade {
    orderId?: string;
}
export interface QueuedPromise<T> {
    resolve: (value: T | PromiseLike<T>) => void;
    reject: (reason?: any) => void;
}
export interface Order {
    id: string;
    marketId: string;
    outcomeId: string;
    side: 'buy' | 'sell';
    type: 'market' | 'limit';
    price?: number;
    amount: number;
    status: 'pending' | 'open' | 'filled' | 'cancelled' | 'rejected';
    filled: number;
    remaining: number;
    timestamp: number;
    fee?: number;
}
export interface Position {
    marketId: string;
    outcomeId: string;
    outcomeLabel: string;
    size: number;
    entryPrice: number;
    currentPrice: number;
    unrealizedPnL: number;
    realizedPnL?: number;
}
export interface Balance {
    currency: string;
    total: number;
    available: number;
    locked: number;
}
export interface CreateOrderParams {
    marketId: string;
    outcomeId: string;
    side: 'buy' | 'sell';
    type: 'market' | 'limit';
    amount: number;
    price?: number;
    fee?: number;
    tickSize?: number;
    negRisk?: boolean;
}
export interface BuiltOrder {
    /** The exchange name this order was built for. */
    exchange: string;
    /** The original params used to build this order. */
    params: CreateOrderParams;
    /**
     * For CLOB exchanges (Polymarket): the EIP-712 signed order
     * ready to POST to the exchange's order endpoint.
     */
    signedOrder?: Record<string, unknown>;
    /**
     * For on-chain AMM exchanges: the EVM transaction payload.
     * Reserved for future exchanges; no current exchange populates this.
     */
    tx?: {
        to: string;
        data: string;
        value: string;
        chainId: number;
    };
    /** The raw, exchange-native payload. Always present. */
    raw: unknown;
}
